/* generated child CSS: 14-pricing/pricing.matrix-collapsible/block.css */
/* lab-ui block · pricing.matrix-collapsible
   Depends: 00-tokens/tokens.css. Light theme. */

.mx-matrix {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
.mx-matrix .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

/* ─── Header ────────────────────────────────────────────────── */
.mx-top {
  max-width: 54rem;
  margin: 0 auto clamp(2rem, 4vw, 3rem);
  text-align: center;
}
.mx-eyebrow {
  margin: 0 0 12px;
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  letter-spacing: var(--type-eyebrow-tracking);
  text-transform: uppercase;
  color: var(--color-text-accent);
}
.mx-title {
  margin: 0 0 12px;
  color: var(--color-heading);
  font-size: var(--type-h2-size);
  font-weight: var(--type-h2-weight);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
}
.mx-lede {
  margin: 0;
  font-size: 1.0625rem;
  line-height: 1.55;
}

/* ─── Column count → grid tracks ───────────────────────────── */
.mx-matrix {
  --mx-feature-col: minmax(180px, 1.6fr);
  --mx-plan-cols: 4;
}
.mx-matrix[data-columns="2"] { --mx-plan-cols: 2; }
.mx-matrix[data-columns="3"] { --mx-plan-cols: 3; }
.mx-matrix[data-columns="4"] { --mx-plan-cols: 4; }

/* ─── Table shell (desktop) ─────────────────────────────────── */
.mx-shell--skeleton {
  display: none;
  border: 1px solid rgba(146, 170, 205, 0.26);
  border-radius: var(--radius-card);
  background: var(--color-white);
  overflow: hidden;
}
.mx-matrix[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) .mx-shell--skeleton {
  display: block;
}
.mx-matrix[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) .mx-shell--table,
.mx-matrix[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) .mx-shell--accordion {
  display: none;
}
.mx-skel-row {
  display: grid;
  grid-template-columns: var(--mx-feature-col) repeat(3, minmax(160px, 1fr));
  gap: 0;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(146, 170, 205, 0.16);
}
.mx-skel-row:last-child { border-bottom: 0; }
.mx-skel-row--head { background: var(--color-gray-bg); }
.mx-skel {
  display: block;
  height: 18px;
  margin-inline-end: 18px;
  border-radius: var(--radius-pill);
  background: linear-gradient(90deg, rgba(146, 170, 205, 0.14), rgba(146, 170, 205, 0.28), rgba(146, 170, 205, 0.14));
  background-size: 200% 100%;
  animation: mx-skeleton 1.2s ease-in-out infinite;
}
.mx-skel--feature { width: 72%; }
.mx-skel--plan { width: 58%; }
.mx-skel--cell { width: 36%; }
@keyframes mx-skeleton {
  to { background-position-x: -200%; }
}

.mx-shell--table {
  position: relative;
  border: 1px solid rgba(146, 170, 205, 0.26);
  border-radius: var(--radius-card);
  background: var(--color-white);
  overflow-x: auto;
  overflow-y: clip;
}
.mx-row {
  display: grid;
  grid-template-columns: var(--mx-feature-col) repeat(var(--mx-plan-cols), minmax(160px, 1fr));
  align-items: stretch;
  min-width: calc(180px + (var(--mx-plan-cols) * 160px));
  border-bottom: 1px solid rgba(146, 170, 205, 0.16);
}
.mx-row:last-child { border-bottom: 0; }
.mx-row--head {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--color-gray-bg);
  border-bottom: 1px solid rgba(146, 170, 205, 0.30);
}

.mx-cell {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding: 16px 18px;
  font-size: 0.9375rem;
  color: var(--color-heading);
  border-right: 1px solid rgba(146, 170, 205, 0.10);
}
.mx-cell:last-child { border-right: 0; }
.mx-cell--feature {
  background: rgba(249, 249, 249, 0.6);
  color: var(--color-heading);
  font-weight: 600;
  border-right: 1px solid rgba(146, 170, 205, 0.22);
}
.mx-cell--plan {
  background: var(--color-gray-bg);
  text-align: left;
}
.mx-plan-name {
  font-size: 1.0625rem;
  font-weight: 650;
  color: var(--color-heading);
}
.mx-plan-tag {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
}
.mx-feature-label { font-weight: 600; }
.mx-feature-hint {
  font-weight: 400;
  font-size: 0.8125rem;
  color: var(--color-gray-blue);
}
.mx-feature-hint:empty { display: none; }

/* ─── Per-row explanation tooltip (data-hint-style="tooltip") ──
   No extra icon: rows that carry explanation text get a custom dotted
   underline (added by block.js) and the label itself is the trigger. */
.mx-feature-tip-source { display: none; }
.mx-matrix[data-hint-style="tooltip"] .mx-feature-label--tip {
  cursor: help;
  text-decoration-line: underline;
  text-decoration-style: dotted;
  text-decoration-thickness: 1.5px;
  text-decoration-color: color-mix(in srgb, var(--color-gray-blue) 55%, transparent);
  text-underline-offset: 4px;
  outline: none;
  transition: text-decoration-color var(--transition-fast), color var(--transition-fast);
}
.mx-matrix[data-hint-style="tooltip"] .mx-feature-label--tip:hover,
.mx-matrix[data-hint-style="tooltip"] .mx-feature-label--tip:focus-visible {
  color: var(--color-heading);
  text-decoration-color: var(--cta-accent);
}
.mx-matrix[data-hint-style="tooltip"] .mx-feature-label--tip:focus-visible {
  outline: 2px solid var(--cta-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

.mx-tip {
  position: fixed;
  z-index: 60;
  max-width: min(280px, 90vw);
  padding: 9px 12px;
  border-radius: var(--radius-card-sm);
  background: var(--color-heading);
  color: var(--color-white);
  font-family: var(--font-family);
  font-size: 0.8125rem;
  font-weight: 400;
  line-height: 1.45;
  letter-spacing: 0;
  text-transform: none;
  box-shadow: var(--shadow-2);
  pointer-events: none;
}
.mx-tip[hidden] { display: none; }
.mx-tip::after {
  content: "";
  position: absolute;
  left: var(--mx-tip-arrow, 50%);
  width: 9px;
  height: 9px;
  background: inherit;
  transform: translateX(-50%) rotate(45deg);
}
.mx-tip[data-placement="top"]::after { bottom: -4px; }
.mx-tip[data-placement="bottom"]::after { top: -4px; }

.mx-mobile-plan { display: none; }
.mx-value {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  min-height: 19px;
  position: relative;
}

/* ─── Cell states ───────────────────────────────────────────── */
.mx-cell[data-state="yes"]     .mx-value::before,
.mx-cell[data-state="partial"] .mx-value::before {
  content: "";
  display: inline-block;
  width: 19px;
  height: 19px;
  border-radius: 999px;
  flex: 0 0 19px;
}
.mx-cell[data-state="yes"]     .mx-value::before { background: var(--color-status-yes, #76D98F); }
.mx-cell[data-state="partial"] .mx-value::before { background: var(--color-status-partial, #D7D9DC); }
.mx-cell[data-state="yes"]     .mx-value::after,
.mx-cell[data-state="partial"] .mx-value::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  width: 8px;
  height: 4px;
  border-left: 2px solid #F9F9F9;
  border-bottom: 2px solid #F9F9F9;
  border-radius: 1px;
  transform: rotate(-45deg);
}
.mx-cell[data-state="yes"] .mx-value:empty,
.mx-cell[data-state="partial"] .mx-value:empty {
  gap: 0;
}
/* "no" reads as a quiet gray dash, not a red X: a column of negative
   marks visually punishes the entry plan. */
.mx-cell[data-state="no"] .mx-value { color: var(--color-gray-blue); }
.mx-cell[data-state="no"] .mx-value:empty::before { content: "—"; }
.mx-cell[data-state="empty"] .mx-value { color: var(--color-gray-blue); }
.mx-cell[data-state="empty"] .mx-value:empty::before { content: "—"; }

/* ─── Group title row ───────────────────────────────────────── */
.mx-group { display: contents; }
.mx-group[data-group-visible="hide"] { display: none; }
.mx-row[data-row-visible="hide"] { display: none; }
.mx-group-title {
  grid-column: 1 / -1;
  padding: 18px 18px 10px;
  background: var(--color-white);
  color: var(--color-text-accent);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(146, 170, 205, 0.20);
  border-top: 1px solid rgba(146, 170, 205, 0.16);
}
.mx-group:first-of-type .mx-group-title { border-top: 0; }

/* ─── Collapsible row groups (desktop opt-in) ───────────────── */
.mx-matrix[data-groups-collapsible="on"] .mx-group-title {
  display: flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
  transition: color var(--transition-fast);
}
.mx-matrix[data-groups-collapsible="on"] .mx-group-title:hover {
  color: var(--color-heading);
}
.mx-group-chev {
  margin-left: auto;
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  /* down = expanded, right = collapsed */
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-2px) rotate(45deg);
  transition: transform var(--transition-fast);
  opacity: 0.65;
}
.mx-matrix[data-groups-collapsible="on"] .mx-group[data-group-collapsed="true"] .mx-group-chev {
  transform: rotate(-45deg);
}
.mx-matrix[data-groups-collapsible="on"] .mx-group[data-group-collapsed="true"] > .mx-row { display: none; }

/* ─── CTA row · closes the table with an action per plan ────── */
.mx-row--cta[data-row-visible="hide"] { display: none; }
.mx-row--cta { background: var(--color-gray-bg); }
.mx-row--cta .mx-cell--feature {
  color: var(--color-gray-blue);
  font-size: 0.8125rem;
}
.mx-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  background:
    linear-gradient(var(--color-white), var(--color-white)) padding-box,
    var(--gradient-cta-ring) border-box;
  border: 1px solid transparent;
  color: var(--color-heading);
  font-size: 0.875rem;
  font-weight: 650;
  line-height: 1.2;
  text-decoration: none;
  text-align: center;
  /* Fills the cell and wraps: a nowrap pill overflows the narrow plan
     columns on tablet widths. */
  white-space: normal;
  overflow-wrap: break-word;
  min-width: 0;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}
.mx-cta:hover {
  transform: translateY(-1px);
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}
.mx-cta[aria-disabled="true"] {
  cursor: not-allowed;
  color: var(--color-gray-blue);
  background: var(--color-gray-bg);
  border-color: rgba(146, 170, 205, 0.28);
  box-shadow: none;
  opacity: 0.72;
}
.mx-cta[aria-disabled="true"]:hover {
  transform: none;
  box-shadow: none;
}
.mx-cta:empty { display: none; }

/* ─── Accordion shell (mobile) ─────────────────────────────── */
.mx-shell--accordion { display: none; }

@media (max-width: 720px) {
