      if (list) {
        const listLabel = section.dataset.pricingFeatureListLabel || list.getAttribute("aria-label") || "";
        if (listLabel) list.setAttribute("aria-label", listLabel);
        list.innerHTML = "";
        for (const feature of featuresByPlan.get(plan.code) || []) {
